/**
 * CDISC controlled terminology per CT package version.
 *
 * `usdm-ts/codelists` is one merged snapshot. This module answers what a codelist
 * contained in a specific published CT package, which is what CDISC CORE checks a
 * coded value against (the package named by its `codeSystemVersion`).
 *
 * The data is generated by `pnpm update-ct-packages` (scripts/build-ct-packages.py).
 * This file is used during development. During build, the JSON import is replaced with embedded data.
 * @packageDocumentation
 */

import ctPackagesJson from "./ct_packages.json" with { type: "json" }

/** The CT package family a codelist is checked against. */
export type CtPackageType = "SDTM" | "DDF"

export interface CtTerm {
  /** NCI concept code, e.g. `C15601`. */
  code: string
  /** CDISC submission value, e.g. `PHASE II TRIAL`. */
  submissionValue: string
  /** NCI preferred term, e.g. `Phase II Trial`. */
  preferredTerm: string
}

/** A codelist as published in one CT package. */
export interface CtCodelist {
  codelistCode: string
  packageType: CtPackageType
  /** Package date, e.g. `2024-09-27`. */
  version: string
  extensible: boolean
  terms: CtTerm[]
}

/** The codelist an `Entity.attribute` is coded with. */
export interface CtAttributeCodelist {
  codelistCode: string
  packageType: CtPackageType
}

/**
 * Stored form of the data. Terms and contents are stored once per codelist and
 * referenced by index, because most codelists do not change between packages.
 * Prefer the accessor functions over reading this directly.
 */
export interface CtPackagesData {
  /** Published package dates per package type, oldest first. */
  packages: Record<CtPackageType, string[]>
  /** `Entity.attribute` keys, the same keys as `usdm-ts/codelists`. */
  attributes: Record<string, CtAttributeCodelist>
  codelists: Record<string, {
    packageType: CtPackageType
    /** Distinct terms over all versions: `[code, submissionValue, preferredTerm]`. */
    terms: [string, string, string][]
    /** Distinct codelist contents; `terms` holds indexes into the terms above. */
    contents: { extensible: boolean; terms: number[] }[]
    /** Package date to index into `contents`. A date is absent when the codelist is not in that package. */
    versions: Record<string, number>
  }>
}

const ctPackages = ctPackagesJson as unknown as CtPackagesData
export default ctPackages

/** Published package dates of a package type, oldest first. */
export function getCtPackageVersions(packageType: CtPackageType): string[] {
  return ctPackages.packages[packageType]
}

/** Whether `version` is the date of a published package of that type. */
export function isCtPackageVersion(packageType: CtPackageType, version: string): boolean {
  return ctPackages.packages[packageType].includes(version)
}

/** The codelist and package type for an `Entity.attribute` key, e.g. `Objective.level`. */
export function getCtAttributeCodelist(attribute: string): CtAttributeCodelist | undefined {
  return Object.hasOwn(ctPackages.attributes, attribute) ? ctPackages.attributes[attribute] : undefined
}

/**
 * A codelist as published in the package of its package type dated `version`.
 * Returns undefined when the codelist is unknown, or does not exist in that package
 * (including when no package of that type has that date).
 */
export function getCtCodelist(codelistCode: string, version: string): CtCodelist | undefined {
  if (!Object.hasOwn(ctPackages.codelists, codelistCode)) return undefined
  const codelist = ctPackages.codelists[codelistCode]
  if (codelist === undefined || !Object.hasOwn(codelist.versions, version)) return undefined
  const contentIndex = codelist.versions[version]
  const content = contentIndex === undefined ? undefined : codelist.contents[contentIndex]
  if (content === undefined) return undefined

  const terms: CtTerm[] = []
  for (const termIndex of content.terms) {
    const term = codelist.terms[termIndex]
    if (term === undefined) continue
    terms.push({ code: term[0], submissionValue: term[1], preferredTerm: term[2] })
  }
  return { codelistCode, packageType: codelist.packageType, version, extensible: content.extensible, terms }
}
